          title: "Kahn 拓扑排序：入度数组 + 队列，附带判环",
          code: "#include <stdio.h>\n#include <string.h>\n\n/* AOV 网 + Kahn 入度法拓扑排序\n   时间复杂度 O(n+e)：每个顶点入队一次，每条弧在输出其起点时被扫描一次\n   空间复杂度 O(n)：入度数组、队列、顶点名数组 */\n#define MAXV 100\n#define MAXE 1000\n\nstatic int head[MAXV];          /* 邻接表头指针：head[u] 是 u 的第一条出弧 */\nstatic int nxt[MAXE], to[MAXE], ecnt = 0;\nstatic int indeg[MAXV];         /* 入度表 */\nstatic int queue[MAXV];         /* 容器：用队列（换成栈只是取出顺序不同） */\nstatic char name[MAXV][8];\n\nstatic void addArc(int u, int v) {\n    to[ecnt] = v; nxt[ecnt] = head[u]; head[u] = ecnt++;\n    indeg[v]++;                 /* 统计入度就在建图时顺手完成 */\n}\n\nint main(void) {\n    int n = 6;\n    static const int arcs[8][2] = {\n        {0, 1}, {0, 2}, {0, 3}, {2, 1}, {2, 4}, {3, 4}, {5, 3}, {5, 4}\n    };\n    int front = 0, rear = 0, i, u, v, cnt = 0;\n\n    memset(head, -1, sizeof(head));\n    for (i = 0; i < n; i++) sprintf(name[i], \"v%d\", i + 1);\n    for (i = 0; i < 8; i++) addArc(arcs[i][0], arcs[i][1]);\n\n    printf(\"初始入度：\");\n    for (i = 0; i < n; i++) printf(\"%s=%d \", name[i], indeg[i]);\n    printf(\"\\n\");\n\n    for (i = 0; i < n; i++)\n        if (indeg[i] == 0) queue[rear++] = i;   /* 入度为 0 的顶点入队 */\n\n    printf(\"拓扑序列：\");\n    while (front < rear) {\n        u = queue[front++];                      /* 出队并输出 */\n        printf(\"%s \", name[u]);\n        cnt++;\n        for (i = head[u]; i != -1; i = nxt[i]) { /* 删去 u 的所有出弧 */\n            v = to[i];\n            if (--indeg[v] == 0) queue[rear++] = v;\n        }\n    }\n    printf(\"\\n输出顶点数 %d / %d -> %s\\n\", cnt, n,\n           cnt < n ? \"存在环，不存在拓扑序列\" : \"无环，序列合法\");\n    return 0;\n}"
