          code: "# 匈牙利算法（Kuhn）：为二分图求最大匹配，核心是不断寻找增广路\n# 时间复杂度 O(V*E)：每个左部顶点做一次 DFS，每次 DFS 最多把每条边访问一次\n\nleft = ['u1', 'u2', 'u3']                             # 左部顶点\nadj = {'u1': ['A', 'B'], 'u2': ['A'], 'u3': ['B']}    # 邻接表：左部 -> 右部\nmatch_right = {}                                      # 右部顶点 -> 已匹配的左部顶点\nmatch_left = {}                                       # 左部顶点 -> 右部顶点\n\n\ndef try_match(u, visited):\n    '''为 u 找一条增广路：右部顶点空闲，或者它的持有者能改配到别处'''\n    for v in adj[u]:\n        if v in visited:            # 本轮已经试过这个右部顶点，跳过\n            continue\n        visited.add(v)\n        if v not in match_right or try_match(match_right[v], visited):\n            match_right[v] = u      # 匹配边翻转：v 改配给 u\n            match_left[u] = v\n            return True\n    return False\n\n\ncount = 0\nfor u in left:\n    ok = try_match(u, set())\n    if ok:\n        count += 1\n    print('为 ' + u + ' 找增广路：' + ('成功，匹配表变为 ' + str(match_left) if ok else '失败（无增广路，暂时搁置）'))\n\nprint('最大匹配数 =', count)\nprint('右部匹配表 =', match_right)\nprint('未匹配的左部顶点 =', [u for u in left if u not in match_left])\nprint('Hall 定理核对：N({u1,u2,u3}) = {A,B}，大小 2 < 3，所以不存在完美匹配')"
